https://www.alanranger.com/blog-on-photo.css:
.ar-bloghub{max-width:1180px;margin:0 auto;font-family:'Proxima Nova','proxima-nova',-apple-system,sans-serif;color:#2b2622}
.ar-bloghub *{box-sizing:border-box}
.ar-bh-top{display:grid;grid-template-columns:1.55fr 1fr;gap:0;border:1px solid #ead9bd;border-radius:16px;overflow:hidden;box-shadow:0 10px 30px rgba(43,38,34,.07)}
.ar-bh-pitch{background:#faf3e6;padding:30px 34px;border-left:5px solid #E57200}
.ar-bh-eyebrow{display:inline-block;font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;color:#fff;background:#E57200;padding:5px 11px;border-radius:5px;margin-bottom:14px}
.ar-bh-h2{margin:0 0 10px;font-size:clamp(24px,3vw,31px);font-weight:800;line-height:1.12;letter-spacing:-.01em;color:#2b2622}
.ar-bh-lead{margin:0 0 9px;font-size:15.5px;line-height:1.55;color:#4a423b;font-weight:500}
.ar-bh-sub{margin:0;font-size:14px;color:#8a7a66;font-weight:600}
.ar-bh-cta{background:#2b2622;padding:28px 28px;display:flex;flex-direction:column;justify-content:center;gap:12px}
.ar-bh-cta-label{font-size:12px;font-weight:800;letter-spacing:.1em;text-transform:uppercase;color:#E57200}
.ar-bh-btn{display:block;text-align:center;text-decoration:none;font-weight:700;font-size:15px;padding:13px 18px;border-radius:9px;transition:transform .15s ease,background .15s ease,color .15s ease}
.ar-bh-btn-solid{background:#E57200;color:#fff !important}
.ar-bh-btn-solid:hover{background:#c45f00;transform:translateY(-1px)}
.ar-bh-btn-ghost{border:1.5px solid #5a5249;color:#f3ede3 !important}
.ar-bh-btn-ghost:hover{border-color:#E57200;color:#fff !important;transform:translateY(-1px)}
.ar-bh-cta-note{margin:2px 0 0;font-size:12.5px;line-height:1.5;color:#a89c8c;font-weight:500}
.ar-bh-doors{display:grid;grid-template-columns:repeat(6,1fr);gap:12px;margin-top:14px}
/* doorway pills: cream to match the intro band + break up above-fold white */
.ar-bh-door{position:relative;display:flex;flex-direction:column;gap:3px;text-decoration:none;background:#faf3e6;border:1px solid #ead9bd;border-radius:12px;padding:15px 16px 16px;overflow:hidden;transition:transform .16s ease,box-shadow .16s ease,border-color .16s ease}
.ar-bh-door:before{content:"";position:absolute;left:0;top:0;height:100%;width:3px;background:#E57200;transform:scaleY(0);transform-origin:bottom;transition:transform .18s ease}
.ar-bh-door:hover{transform:translateY(-3px);box-shadow:0 10px 22px rgba(43,38,34,.12);border-color:#E57200}
.ar-bh-door:hover:before{transform:scaleY(1)}
/* punchier eyebrow (deeper orange) + strong dark title, both pop on cream */
.ar-bh-door-k{font-size:11px;font-weight:800;letter-spacing:.05em;text-transform:uppercase;color:#c45f00}
.ar-bh-door-t{font-size:15.5px;font-weight:800;color:#2b2622;line-height:1.2}
.ar-bh-door:after{content:"→";position:absolute;right:14px;bottom:13px;font-size:15px;color:#E57200;opacity:0;transform:translateX(-4px);transition:opacity .18s ease,transform .18s ease}
.ar-bh-door:hover:after{opacity:1;transform:translateX(0)}
@media(max-width:900px){.ar-bh-doors{grid-template-columns:repeat(3,1fr)}}
@media(max-width:680px){
  .ar-bh-top{grid-template-columns:1fr}
  .ar-bh-pitch{padding:24px 22px}.ar-bh-cta{padding:22px}
  .ar-bh-doors{grid-template-columns:repeat(2,1fr);gap:10px}
  .ar-bh-door{padding:13px 14px 26px}.ar-bh-door:after{opacity:1;transform:none}
}
@media(prefers-reduced-motion:reduce){.ar-bh-btn,.ar-bh-door,.ar-bh-door:before,.ar-bh-door:after{transition:none}}

.ar-partners{max-width:1180px;margin:30px auto 0;font-family:'Proxima Nova','proxima-nova',-apple-system,sans-serif;color:#2b2622}
.ar-partners *{box-sizing:border-box}
.ar-partners-head{display:flex;align-items:baseline;gap:12px;flex-wrap:wrap;margin-bottom:14px;padding-bottom:9px;border-bottom:2px solid #ead9bd}
