article.BlogItem .ar-bpl-wrap{--o:#f15a22;--o-light:#ff9e6e;--o-darker:#8c2c0a;--cream:#fef7ed;--card-cream:#faf7f2;--card-border:#f3d9c8;--navy:#0f172a;--navy-2:#1e293b;--slate:#334155;--slate-muted:#64748b;
max-width:760px;margin:0 auto;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:var(--slate);font-size:1rem;line-height:1.65;}
article.BlogItem .ar-bpl-wrap p{margin:0 0 1rem;}
article.BlogItem .ar-bpl-wrap a{color:var(--o-darker) !important;text-decoration:underline !important;text-decoration-color:rgba(241,90,34,.4) !important;text-underline-offset:3px;font-weight:700;}
article.BlogItem .ar-bpl-wrap a:hover{text-decoration-color:var(--o) !important;}
article.BlogItem .ar-bpl-tag{display:inline-block;background:#fff;color:var(--o-darker) !important;font-size:.68rem;font-weight:800;letter-spacing:.05em;text-transform:uppercase;padding:.35rem .75rem;border-radius:999px;border:1px solid var(--o);margin:0 0 .7rem;}
article.BlogItem .ar-bpl-wrap h2{margin:0 0 1rem !important;font-size:1.45rem !important;font-weight:800 !important;color:var(--navy) !important;line-height:1.3;position:relative;display:inline-block;padding-bottom:.35rem;text-transform:none !important;letter-spacing:normal !important;}
article.BlogItem .ar-bpl-wrap h2::after{content:"";position:absolute;left:0;bottom:0;width:60px;height:3px;background:var(--o);border-radius:2px;}
article.BlogItem .ar-bpl-wrap h3{margin:1.4rem 0 .6rem !important;font-size:1.08rem !important;font-weight:800 !important;color:var(--navy) !important;text-transform:none !important;}

article.BlogItem .ar-bpl-band{border-radius:20px;padding:1.8rem 1.8rem 1.2rem;margin:0 0 1.6rem;}
article.BlogItem .ar-bpl-band--cream{background:var(--cream);border:1px solid var(--card-border);}
article.BlogItem .ar-bpl-band--plain{padding:0.4rem 0 0.2rem;}
article.BlogItem .ar-bpl-band--navy{background:var(--navy);}
article.BlogItem .ar-bpl-band--navy p{color:#cbd5e1 !important;}
article.BlogItem .ar-bpl-band--navy h2{color:#fff !important;}
article.BlogItem .ar-bpl-band--navy h3{color:#fff !important;}
article.BlogItem .ar-bpl-band--navy a{color:var(--o-light) !important;text-decoration-color:rgba(255,158,110,.5) !important;}
article.BlogItem .ar-bpl-band--navy a:hover{text-decoration-color:var(--o-light) !important;}
article.BlogItem .ar-bpl-band--navy .ar-bpl-tag{background:transparent;color:var(--o-light) !important;border-color:var(--o);}

article.BlogItem .ar-bpl-learn{counter-reset:arbpl;}
article.BlogItem .ar-bpl-learn h3{padding-left:38px;position:relative;}
article.BlogItem .ar-bpl-learn h3::before{counter-increment:arbpl;content:counter(arbpl);position:absolute;left:0;top:-2px;display:inline-flex;align-items:center;justify-content:center;width:26px;height:26px;border-radius:50%;background:var(--o);color:#fff;font-size:.85rem;font-weight:800;}

article.BlogItem .ar-bpl-card{background:#fff;border:1px solid var(--card-border);border-left:4px solid var(--o);border-radius:12px;padding:1.15rem 1.3rem;margin:0 0 1rem;}
article.BlogItem .ar-bpl-band--navy .ar-bpl-card{background:var(--navy-2);border-color:#334155;}
article.BlogItem .ar-bpl-band--navy .ar-bpl-card p{color:#e2e8f0 !important;}
article.BlogItem .ar-bpl-band--navy .ar-bpl-card strong{color:#fff !important;}

article.BlogItem .ar-bpl-grid{display:grid;grid-template-columns:1fr 1fr;gap:.85rem;margin:1.2rem 0;}
article.BlogItem .ar-bpl-route{display:block;background:#fff;border:1px solid var(--card-border);border-left:4px solid transparent;border-radius:10px;padding:1.05rem 1.15rem;text-decoration:none !important;transition:border-color .18s ease,background .18s ease,box-shadow .18s ease;}
article.BlogItem .ar-bpl-route:hover{background:var(--card-cream);border-left-color:var(--o);box-shadow:0 4px 12px rgba(15,23,42,.06);}
article.BlogItem .ar-bpl-route-title{display:block;font-weight:800;font-size:.95rem;color:var(--o-darker) !important;line-height:1.35;margin-bottom:.35rem;text-decoration:underline !important;text-decoration-color:rgba(241,90,34,.4) !important;text-underline-offset:3px;}
article.BlogItem .ar-bpl-route:hover .ar-bpl-route-title{text-decoration-color:var(--o) !important;}
article.BlogItem .ar-bpl-route-desc{display:block;font-size:.84rem;color:var(--slate-muted) !important;line-height:1.55;text-decoration:none !important;}

article.BlogItem .ar-bpl-faq{background:#fff;border:1px solid var(--card-border);border-left:4px solid transparent;border-radius:10px;margin-bottom:.65rem;overflow:hidden;transition:border-color .18s ease,background .18s ease;}
article.BlogItem .ar-bpl-faq[open]{background:var(--card-cream);border-left-color:var(--o);}
article.BlogItem .ar-bpl-q{padding:1rem 1.25rem;font-weight:800;font-size:.95rem;color:var(--navy) !important;cursor:pointer;display:flex;justify-content:space-between;gap:1rem;list-style:none;}
article.BlogItem .ar-bpl-q::-webkit-details-marker{display:none;}
article.BlogItem .ar-bpl-qi{flex:0 0 20px;color:var(--o) !important;font-size:1.2rem;font-weight:800;line-height:1;transition:transform .18s ease;}
article.BlogItem .ar-bpl-faq[open] .ar-bpl-qi{transform:rotate(45deg);}
article.BlogItem .ar-bpl-a{padding:0 1.25rem 1.1rem;font-size:.9rem;line-height:1.6;}

article.BlogItem .ar-bpl-cta{text-align:center;padding:2rem 1.8rem;}
article.BlogItem .ar-bpl-cta h3{margin:0 0 .5rem !important;font-size:1.25rem !important;padding-left:0 !important;}
article.BlogItem .ar-bpl-btn{display:inline-block;background:var(--o);color:#fff !important;font-weight:800;font-size:.92rem;padding:.7rem 1.4rem;border-radius:999px;text-decoration:none !important;margin:.5rem .3rem 0;}
article.BlogItem .ar-bpl-btn:hover{background:#d3420d;}
article.BlogItem .ar-bpl-btn--ghost{background:transparent;color:var(--o-light) !important;border:1px solid var(--o);}
article.BlogItem .ar-bpl-btn--ghost:hover{background:var(--navy-2);}
@media(max-width:640px){article.BlogItem .ar-bpl-grid{grid-template-columns:1fr;}article.BlogItem .ar-bpl-wrap h2{font-size:1.3rem !important;}article.BlogItem .ar-bpl-band{padding:1.3rem 1.2rem .8rem;}}

