.ar-jlrb {
  --orange:#E57200;
  --orange-d:#c45f00;
  --cream:#faf7f3;
  --panel:#2b2622;
  --ink:#2b2622;
  --muted:#6b625c;
  --line:#e7ddd2;
  font-family:"Proxima Nova","Helvetica Neue",Arial,sans-serif;
  color:var(--ink);
  line-height:1.7;
  font-size:17px;
