}

.ar-jlrb p {
  margin:0 0 20px;
}

.ar-jlrb h2 {
  font-size:26px;
  font-weight:800;
  line-height:1.2;
  margin:42px 0 14px;
}

.ar-jlrb h3 {
  font-size:20px;
  font-weight:800;
  margin:30px 0 10px;
}

.ar-jlrb a {
  color:var(--orange-d);
}

.ar-jlrb .ar-jlrb-lede {
  font-size:20px;
  color:#403a35;
  border-left:4px solid var(--orange);
  padding-left:18px;
  margin:0 0 28px;
}

.ar-jlrb .ar-jlrb-pull {
  font-size:22px;
  font-weight:800;
  color:var(--ink);
  background:var(--cream);
  border-radius:14px;
  padding:24px 26px;
  margin:30px 0;
  line-height:1.3;
}

.ar-jlrb .ar-jlrb-callout {
