}

.ar-jlrb .ar-jlrb-callout h3 {
  margin-top:0;
  color:var(--orange-d);
}

.ar-jlrb ul {
  margin:0 0 20px;
  padding-left:22px;
}

.ar-jlrb ul li {
  margin-bottom:8px;
}

.ar-jlrb .ar-jlrb-revs {
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:18px;
  margin:26px 0;
}

.ar-jlrb-rev {
  background:#fff;
  border:1px solid var(--line);
  border-top:4px solid var(--orange);
  border-radius:14px;
  padding:24px 22px 20px;
  margin:0;
  box-shadow:0 6px 18px rgba(43,38,34,.06);
  position:relative;
}

.ar-jlrb-rev::before {
  content:"\201C";
  position:absolute;
  top:6px;
  right:18px;
  font-family:Georgia,serif;
  font-size:64px;
  line-height:1;
  color:#ffe2cc;
  font-weight:700;
}

.ar-jlrb-stars {
