}

.ar-jlrb-rev blockquote {
  margin:0 0 14px;
  font-size:15.5px;
  color:#332d28;
  line-height:1.6;
  font-weight:500;
  position:relative;
  z-index:1;
}

.ar-jlrb-rev figcaption {
