  overflow:hidden;
}
.ar-jlrb-faq summary {
  cursor:pointer;
  font-weight:800;
  font-size:16.5px;
  padding:16px 20px;
  list-style:none;
  position:relative;
  padding-right:48px;
  color:var(--ink);
}
.ar-jlrb-faq summary::-webkit-details-marker {
  display:none;
}
.ar-jlrb-faq summary::after {
  content:"+";
  position:absolute;
  right:20px;
  top:50%;
  transform:translateY(-50%);
  font-size:24px;
  font-weight:400;
  color:var(--orange);
  transition:transform .2s ease;
}
.ar-jlrb-faq[open] summary::after {
  content:"\2212";
}
.ar-jlrb-faq[open] summary {
  color:var(--orange-d);
}
.ar-jlrb-faq-a {
  padding:0 20px 18px;
}
.ar-jlrb-faq-a p {
