.ar-welcome{--orange:#E57200;--arrow:#b8430a;--ink:#1a1a1a;font-family:'proxima-nova','Proxima Nova','Helvetica Neue',Arial,sans-serif;max-width:1180px;margin:0 auto;color:#1f242a;}
.ar-welcome *{box-sizing:border-box;}
.ar-welcome .ar-row{display:grid;grid-template-columns:1fr 1.05fr;gap:64px;align-items:start;}
.ar-welcome .ar-left{padding-top:6px;}
.ar-welcome .ar-eyebrow{font-size:15px;font-weight:500;color:#9a9a96;margin:0 0 12px;}
.ar-welcome .ar-h2{font-size:36px;font-weight:600;color:rgba(0,0,0,.9);line-height:1.18;margin:0 0 18px;}
.ar-welcome .ar-rule{border:0;border-top:3px solid var(--orange);margin:0 0 22px;width:64px;}
.ar-welcome .ar-intro{font-size:17.5px;font-weight:400;color:#3a3a36;line-height:1.6;margin:0 0 18px;}
.ar-welcome .ar-cred{font-size:14.5px;font-weight:500;color:#8a8a86;margin:0;}
.ar-welcome .ar-right{border:2px solid var(--orange);border-radius:16px;padding:34px 38px;box-shadow:0 10px 30px rgba(229,114,0,.08);}
.ar-welcome .ar-h3{font-size:26px;font-weight:600;color:rgba(0,0,0,.9);line-height:1.25;margin:0 0 16px;}
.ar-welcome .ar-lede{font-size:17.5px;font-weight:400;color:#3a3a36;line-height:1.55;margin:0 0 26px;}
.ar-welcome .ar-doors{border-top:1px solid #ececec;}
.ar-welcome .ar-doors a{display:flex;justify-content:space-between;align-items:center;padding:19px 2px;border-bottom:1px solid #ececec;text-decoration:none;color:var(--orange) !important;font-size:18px;font-weight:700;transition:color .15s;}
.ar-welcome .ar-doors a:hover{color:#c45f00 !important;}
.ar-welcome .ar-doors a:hover .ar-ar{transform:translateX(5px);}
.ar-welcome .ar-doors a .ar-ar{color:var(--arrow);font-weight:900;font-size:24px;line-height:1;transition:transform .15s;}
@media(max-width:760px){
  .ar-welcome .ar-row{grid-template-columns:1fr;gap:28px;}
  .ar-welcome .ar-right{padding:26px 24px;}
  .ar-welcome .ar-h2{font-size:30px;}
}

@import url('https://fonts.googleapis.com/css2?family=Caveat:wght@600&display=swap');
.ar-meet{--orange:#E57200;--arrow:#b8430a;font-family:'proxima-nova','Proxima Nova','Helvetica Neue',Arial,sans-serif;max-width:1180px;margin:0 auto;color:#1f242a;}
.ar-meet *{box-sizing:border-box;}
.ar-meet .ar-row{display:grid;grid-template-columns:0.9fr 1.1fr;gap:48px;align-items:center;}
.ar-meet .ar-photo{border-radius:3px;overflow:hidden;min-height:440px;background:#e9e4dc;}
.ar-meet .ar-photo img{width:100%;height:100%;min-height:440px;object-fit:cover;display:block;}
.ar-meet .ar-note{background:#faf3e6;border:1px solid #ead9bd;border-radius:3px;padding:34px 40px;box-shadow:0 2px 0 #ead9bd, 0 14px 28px rgba(120,90,40,.10);}
.ar-meet .ar-script{font-family:'Caveat','Segoe Script',cursive;font-size:30px;font-weight:600;color:var(--arrow);line-height:1;margin:0 0 6px;}
.ar-meet .ar-h3{font-size:28px;font-weight:600;color:rgba(0,0,0,.9);line-height:1.2;margin:4px 0 18px;}
.ar-meet .ar-note p{font-size:16.5px;color:#3a3a36;line-height:1.6;margin:0 0 14px;}
.ar-meet .ar-note p:last-of-type{margin-bottom:24px;}
.ar-meet .ar-sign{display:flex;align-items:center;gap:26px;border-top:1px solid #ecd9c2;padding-top:20px;flex-wrap:wrap;}
.ar-meet .ar-sign img.sig{height:78px;width:auto;}
.ar-meet .ar-sign img.crest{height:66px;width:auto;}
.ar-meet .ar-more{margin-left:auto;color:var(--orange) !important;font-weight:700;font-size:16px;text-decoration:none;white-space:nowrap;}
.ar-meet .ar-more .ar-ar{color:var(--arrow);font-weight:900;font-size:20px;display:inline-block;transition:transform .15s;}
.ar-meet .ar-more:hover .ar-ar{transform:translateX(4px);}
@media(max-width:760px){
  .ar-meet .ar-row{grid-template-columns:1fr;gap:26px;}
  .ar-meet .ar-photo,.ar-meet .ar-photo img{min-height:320px;}
  .ar-meet .ar-note{padding:28px 26px;}
  .ar-meet .ar-script{font-size:26px;}
  .ar-meet .ar-sign img.sig{height:64px;}
  .ar-meet .ar-more{margin-left:0;width:100%;}
}

.ar-learn{--orange:#E57200;--orange-d:#c45f00;--arrow:#b8430a;font-family:'proxima-nova','Proxima Nova','Helvetica Neue',Arial,sans-serif;max-width:1180px;margin:0 auto;color:#1f242a;}
.ar-learn *{box-sizing:border-box;}
.ar-learn .ar-row{display:grid;grid-template-columns:1.1fr 0.9fr;gap:52px;align-items:center;}
.ar-learn .ar-eyebrow{font-size:15px;font-weight:500;color:#9a9a96;margin:0 0 12px;}
.ar-learn .ar-h2{font-size:36px;font-weight:600;color:rgba(0,0,0,.9);line-height:1.18;margin:0 0 16px;}
.ar-learn .ar-intro{font-size:16.5px;color:#3a3a36;line-height:1.6;margin:0 0 22px;max-width:560px;}
.ar-learn .ar-cards{display:grid;grid-template-columns:1fr 1fr;gap:14px;}
.ar-learn .ar-card{text-decoration:none;display:flex;justify-content:space-between;align-items:center;border:1px solid #eee;border-left:3px solid var(--orange);border-radius:10px;padding:18px 20px;background:#fff;box-shadow:0 4px 14px rgba(0,0,0,.04);transition:transform .18s cubic-bezier(.34,1.56,.64,1),box-shadow .18s,border-color .18s,background .18s;}
.ar-learn .ar-card:hover{transform:translateY(-3px) rotate(-.6deg);box-shadow:0 12px 26px rgba(229,114,0,.18);border-color:var(--orange);background:#fffaf3;}
.ar-learn .ar-card .t{font-size:16px;font-weight:700;color:var(--orange-d);margin:0 0 3px;}
.ar-learn .ar-card .s{font-size:12.5px;color:#6b6b66;}
.ar-learn .ar-card .ar-ar{color:var(--arrow);font-weight:900;font-size:20px;flex-shrink:0;margin-left:12px;transition:transform .18s;}
.ar-learn .ar-card:hover .ar-ar{transform:translateX(5px);}
/* Coherent in-between treatment: muted colour + faint warm tone */
.ar-learn .ar-mosaic{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:8px;border-radius:4px;overflow:hidden;aspect-ratio:1/1.04;}
.ar-learn .ar-mosaic .tile{position:relative;overflow:hidden;background:#e9e4dc;display:block;text-decoration:none;}
.ar-learn .ar-mosaic .tile img{width:100%;height:100%;object-fit:cover;display:block;filter:grayscale(45%) sepia(12%) saturate(85%) contrast(1.03);transition:filter .3s,transform .3s;}
