.ar-so .ar-so-hero{position:relative;overflow:hidden;background:#faf3e6;border:1px solid #ead9bd;border-radius:6px;box-shadow:0 2px 0 #ead9bd,0 14px 28px rgba(120,90,40,.10);display:flex;align-items:center;gap:36px;padding:30px 36px;}
