#ar-ll .ar-ll-strip .k{font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:#9a6b2f;font-weight:700;margin-bottom:6px;display:inline-block;border-bottom:1.5px solid #1a1a1a;padding-bottom:3px}
