#ar-ll .ar-ll-c{position:relative;display:block;text-decoration:none;border:1.5px solid #dcc6aa;border-radius:8px;padding:12px 13px 30px;background:#fdf6ee;cursor:pointer;transition:transform .15s ease,box-shadow .15s ease,border-color .15s ease,background .15s ease}
#ar-ll .ar-ll-c:before{content:"Select option \2192";position:absolute;left:13px;bottom:9px;font-size:11px;font-weight:700;letter-spacing:.02em;color:#e8853d;opacity:.85;transition:opacity .15s ease,transform .15s ease}
#ar-ll .ar-ll-c:hover{border-color:#e8853d;transform:translateY(-3px);box-shadow:0 6px 16px rgba(154,77,16,.22);background:#fffaf4}
#ar-ll .ar-ll-c:hover:before{opacity:1;transform:translateX(3px)}
#ar-ll .ar-ll-c:focus-visible{outline:3px solid rgba(232,133,61,.55);outline-offset:2px}
#ar-ll .ar-ll-c.sel{background:#f9e3c8;border:3px solid #9a4d0f;box-shadow:0 2px 10px rgba(154,77,16,.25);transform:none;padding:10.5px 11.5px 28.5px}
#ar-ll .ar-ll-c.sel:before{content:"\2713 Selected";color:#2e7d32;opacity:1;font-weight:800}
#ar-ll .ar-ll-c.sel:after{content:"\2713";position:absolute;top:8px;right:8px;width:22px;height:22px;border-radius:50%;background:#2e7d32;color:#fff;font-size:13px;font-weight:800;display:flex;align-items:center;justify-content:center}
#ar-ll .ar-ll-c.out{cursor:default;border-style:dashed;padding:12px 13px;pointer-events:none}
#ar-ll .ar-ll-c.out:before{display:none}
#ar-ll .ar-ll-c.out:after{content:"UNAVAILABLE";position:absolute;top:8px;right:8px;background:#c62828;color:#fff;font-size:10px;font-weight:800;letter-spacing:.06em;padding:4px 9px;border-radius:11px}
#ar-ll .ar-ll-d{font-weight:700;font-size:15px;color:#1a1a1a;line-height:1.35;padding-right:24px}
#ar-ll .ar-ll-t{font-size:13px;font-weight:600;color:#555;margin-top:3px}
#ar-ll .ar-ll-p{font-size:18px;font-weight:800;margin-top:8px;color:#1a1a1a}
#ar-ll .ar-ll-p .was{font-size:13px;font-weight:600;color:#9a8a78;text-decoration:line-through;margin-left:8px}
#ar-ll .ar-ll-p .save{display:inline-block;margin-left:8px;font-size:11px;font-weight:800;color:#fff;background:#2e7d32;border-radius:6px;padding:2px 7px;letter-spacing:.03em;vertical-align:middle}
