.ar-eyebrow{display:inline-block;background:#E57200;color:#fff;font-size:12px;font-weight:700;text-transform:uppercase;letter-spacing:.08em;padding:4px 11px;border-radius:4px;margin-bottom:13px}
.ar-hero-pitch h2{font-size:21px;font-weight:700;color:#c45f00;line-height:1.18;margin:0 0 12px}
.ar-hero-pitch p{font-size:15px;font-weight:600;color:#1f242a;margin:0 0 11px}
