.ar-facts{display:flex;flex-wrap:wrap;gap:8px;margin:10px 0 0}
.ar-fact{background:#fff;border:1px solid #E57200;color:#c45f00;font-size:12.5px;font-weight:700;padding:5px 11px;border-radius:999px}
.ar-hero-action{background:#2b2622;color:#fff;padding:26px;display:flex;flex-direction:column;justify-content:center}
.ar-action-label{font-size:12.5px;font-weight:800;color:#E57200;text-transform:uppercase;letter-spacing:.06em;margin:0 0 12px}
.ar-btn{display:block;text-align:center;font-size:15px;font-weight:700;padding:13px 16px;border-radius:9px;margin-bottom:9px;background:#E57200 !important;color:#fff !important;box-shadow:0 4px 14px rgba(229,114,0,.30);text-decoration:none}
.ar-btn:hover{background:#cf6700 !important}
.ar-btn-ghost{display:block;text-align:center;font-size:15px;font-weight:600;padding:13px 16px;border-radius:9px;margin-bottom:9px;background:transparent !important;border:1.5px solid rgba(255,255,255,.4);color:#fff !important;text-decoration:none}
.ar-callpill{display:flex;align-items:center;justify-content:center;gap:8px;background:#fff !important;border:1.5px solid #1e8e3e;border-radius:9px;padding:11px 16px;margin-bottom:9px}
.ar-callme{font-size:14px;font-weight:800;color:#1e8e3e !important}
.ar-callnum{font-size:15px;font-weight:800;color:#111827 !important}
.ar-msg{display:block;text-align:center;font-size:13px;font-weight:700;color:#FBBC04;text-decoration:underline;margin-top:2px}
.ar-proof{font-size:13px;font-weight:500;color:#c9c2b9;border-top:1px solid rgba(255,255,255,.14);padding-top:13px;margin:11px 0 0}
.ar-proof strong{color:#fff}
