#ar-tuition-cta{
  --ar-orange:#E57200;
  --ar-ink:#111827;
  --ar-muted:#6b7280;
  --ar-line:rgba(17,24,39,.14);
  --ar-bg:#ffffff;
  --ar-soft:#f9fafb;
  --ar-radius:16px;
  font-family: system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  color: var(--ar-ink);
}
#ar-tuition-cta .ar-wrap{max-width:1200px;margin:0 auto;padding:18px 10px;}
#ar-tuition-cta .ar-title{margin:0 0 12px 0;font-size:clamp(22px,2.3vw,30px);line-height:1.15;letter-spacing:-0.02em;}
#ar-tuition-cta .ar-sub{margin:0 0 18px 0;color:var(--ar-muted);font-size:15px;line-height:1.5;}
#ar-tuition-cta .ar-grid{display:grid;grid-template-columns:repeat(12,1fr);gap:14px;}

#ar-tuition-cta .ar-card{
  grid-column:span 12;background:var(--ar-bg);border:1px solid var(--ar-line);
  border-radius:var(--ar-radius);padding:16px 16px 14px;box-shadow:0 6px 18px rgba(17,24,39,.06);
  display:flex;flex-direction:column;gap:12px;position:relative;overflow:hidden;
}
#ar-tuition-cta .ar-card:before{content:"";position:absolute;inset:0 0 auto 0;height:4px;background:var(--ar-orange);opacity:.95;}
#ar-tuition-cta .ar-head{display:flex;align-items:flex-start;gap:12px;padding-top:2px;}
#ar-tuition-cta .ar-icon{
  width:44px;height:44px;border-radius:12px;background:rgba(229,114,0,.10);
  display:grid;place-items:center;flex:0 0 auto;
}
#ar-tuition-cta .ar-icon svg{width:24px;height:24px;fill:var(--ar-orange);}
#ar-tuition-cta .ar-hgroup{min-width:0;}
#ar-tuition-cta .ar-card h3{margin:0;font-size:18px;line-height:1.25;letter-spacing:-0.01em;}
#ar-tuition-cta .ar-card h3 a{color:var(--ar-ink);text-decoration:none;border-bottom:1px solid rgba(229,114,0,.35);}
#ar-tuition-cta .ar-card h3 a:hover{color:var(--ar-orange);border-bottom-color:rgba(229,114,0,.75);}

#ar-tuition-cta .ar-meta{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px;}
#ar-tuition-cta .ar-pill{
  font-size:12px;line-height:1;padding:8px 10px;border-radius:999px;
  background:var(--ar-soft);border:1px solid var(--ar-line);color:var(--ar-ink);white-space:nowrap;
}
#ar-tuition-cta .ar-pill b{font-weight:800;margin-right:6px;}
#ar-tuition-cta .ar-where{margin-top:8px;font-size:13px;color:var(--ar-muted);line-height:1.45;}

#ar-tuition-cta .ar-best{margin:0;padding:0;list-style:none;display:grid;gap:6px;color:var(--ar-ink);font-size:14px;line-height:1.45;}
#ar-tuition-cta .ar-best li{position:relative;padding-left:18px;}
#ar-tuition-cta .ar-best li:before{
  content:"";width:8px;height:8px;border-radius:999px;background:var(--ar-orange);
  position:absolute;left:0;top:0.5em;transform:translateY(-50%);
}

#ar-tuition-cta details{border:1px solid var(--ar-line);border-radius:14px;background:#fff;overflow:hidden;}
#ar-tuition-cta details summary{
  cursor:pointer;list-style:none;padding:10px 12px;font-weight:900;font-size:13px;
  display:flex;align-items:center;justify-content:space-between;gap:10px;
}
#ar-tuition-cta details summary::-webkit-details-marker{display:none;}
#ar-tuition-cta details summary:after{
  content:"";width:10px;height:10px;border-right:2px solid rgba(17,24,39,.6);border-bottom:2px solid rgba(17,24,39,.6);
  transform:rotate(45deg);transition:transform .12s ease;margin-left:auto;
}
#ar-tuition-cta details[open] summary:after{transform:rotate(-135deg);}
#ar-tuition-cta .ar-acc-body{padding:0 12px 12px;border-top:1px solid var(--ar-line);background:var(--ar-soft);font-size:14px;line-height:1.5;color:var(--ar-ink);}
#ar-tuition-cta .ar-acc-body p{margin:10px 0 0;}
#ar-tuition-cta .ar-acc-body ul{margin:8px 0 0;padding:0 0 0 18px;}
#ar-tuition-cta .ar-acc-body li{margin:6px 0;}

#ar-tuition-cta .ar-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:2px;}
#ar-tuition-cta .ar-btn{
  display:inline-flex;align-items:center;justify-content:center;gap:8px;
  padding:10px 12px;border-radius:12px;font-weight:900;font-size:14px;text-decoration:none;
  border:1px solid transparent;transition:transform .06s ease, box-shadow .12s ease, background .12s ease, border-color .12s ease;
  user-select:none;
}
#ar-tuition-cta .ar-btn:active{transform:translateY(1px);}
#ar-tuition-cta .ar-btn-primary{background:var(--ar-orange);color:#fff;box-shadow:0 10px 22px rgba(229,114,0,.22);}
#ar-tuition-cta .ar-btn-primary:hover{box-shadow:0 14px 28px rgba(229,114,0,.28);}
#ar-tuition-cta .ar-btn-secondary{background:#fff;color:var(--ar-ink);border-color:var(--ar-line);}
#ar-tuition-cta .ar-btn-secondary:hover{border-color:rgba(229,114,0,.45);box-shadow:0 10px 22px rgba(17,24,39,.08);}

#ar-tuition-cta .ar-packages{
  margin-top:14px;border:1px solid var(--ar-line);border-radius:var(--ar-radius);
  background:linear-gradient(180deg, rgba(229,114,0,.08), rgba(229,114,0,.03));
  padding:14px;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;
}
#ar-tuition-cta .ar-packages strong{font-size:14px;letter-spacing:-0.01em;}
#ar-tuition-cta .ar-pack-links{display:flex;flex-wrap:wrap;gap:10px;}
#ar-tuition-cta .ar-packages a{
  display:inline-flex;align-items:center;gap:8px;padding:9px 11px;border-radius:12px;background:#fff;
  border:1px solid var(--ar-line);text-decoration:none;color:var(--ar-ink);font-weight:900;font-size:13px;
}
#ar-tuition-cta .ar-packages a:hover{border-color:rgba(229,114,0,.45);box-shadow:0 10px 22px rgba(17,24,39,.08);}

@media (min-width:740px){#ar-tuition-cta .ar-card{grid-column:span 6;}}
@media (min-width:1020px){#ar-tuition-cta .ar-card{grid-column:span 4;}}

