#ar-ll .ar-ll-strip .c.tip{cursor:help}
#ar-ll .ar-ll-strip .c.tip:hover:before{content:attr(data-tip);position:absolute;bottom:calc(100% + 10px);left:50%;transform:translateX(-50%);width:260px;background:#1a1a1a;color:#fff;font:500 12.5px/1.5 'Proxima Nova',sans-serif;text-transform:none;letter-spacing:0;padding:10px 13px;border-radius:8px;z-index:99999;box-shadow:0 6px 20px rgba(0,0,0,.25);white-space:normal;text-align:left}
#ar-ll .ar-ll-strip .c.tip:hover:after{content:"";position:absolute;bottom:calc(100% + 4px);left:50%;transform:translateX(-50%);border:6px solid transparent;border-top-color:#1a1a1a}
#ar-ll .ar-ll-sum{display:grid;grid-template-columns:160px 1fr;column-gap:14px;font-size:14px;line-height:1.55;color:#33271b}
#ar-ll .ar-ll-lab{color:#7a5320;font-weight:700;display:flex;align-items:flex-start;gap:7px;padding:9px 0;border-top:1px solid #efe2cd}
#ar-ll .ar-ll-lab:before{content:"";width:7px;height:7px;border-radius:50%;background:#c96a1e;display:inline-block;flex:none;margin-top:6px}
