/* date tiles */
#ar-ll .ar-ll-g{display:grid;grid-template-columns:1fr 1fr 1fr;gap:10px}
#ar-ll .ar-ll-c{position:relative;display:block;text-decoration:none;border:1.5px solid #dcc6aa;border-radius:8px;padding:12px 13px 30px;background:#fdf6ee;cursor:pointer;transition:transform .15s ease,box-shadow .15s ease,border-color .15s ease,background .15s ease}
#ar-ll .ar-ll-c:before{content:"Select date \2192";position:absolute;left:13px;bottom:9px;font-size:11px;font-weight:700;letter-spacing:.02em;color:#e8853d;opacity:.85;transition:opacity .15s ease,transform .15s ease}
#ar-ll .ar-ll-c:hover{border-color:#e8853d;transform:translateY(-3px);box-shadow:0 6px 16px rgba(154,77,16,.22);background:#fffaf4}
#ar-ll .ar-ll-c:hover:before{opacity:1;transform:translateX(3px)}
#ar-ll .ar-ll-c:focus-visible{outline:3px solid rgba(232,133,61,.55);outline-offset:2px}
#ar-ll .ar-ll-c.sel{background:#f9e3c8;border:3px solid #9a4d0f;box-shadow:0 2px 10px rgba(154,77,16,.25);transform:none;padding:10.5px 11.5px 28.5px}
#ar-ll .ar-ll-c.sel:before{content:"\2713 Selected";color:#2e7d32;opacity:1;font-weight:800}
#ar-ll .ar-ll-c.sel:after{content:"\2713";position:absolute;top:8px;right:8px;width:22px;height:22px;border-radius:50%;background:#2e7d32;color:#fff;font-size:13px;font-weight:800;display:flex;align-items:center;justify-content:center}
#ar-ll .ar-ll-c.out{cursor:default;border-style:dashed;padding:12px 13px;pointer-events:none}
#ar-ll .ar-ll-c.out:before{display:none}
#ar-ll .ar-ll-c.out:after{content:"SOLD OUT";position:absolute;top:8px;right:8px;background:#c62828;color:#fff;font-size:10px;font-weight:800;letter-spacing:.06em;padding:4px 9px;border-radius:11px}
#ar-ll .ar-ll-d{font-weight:700;font-size:15px;color:#1a1a1a;line-height:1.35;padding-right:24px}
#ar-ll .ar-ll-c.out .ar-ll-d{padding-right:74px}
#ar-ll .ar-ll-t{font-size:13px;font-weight:600;color:#555;margin-top:3px}
#ar-ll .ar-ll-a{font-size:12px;color:#3a8a3a;margin-top:6px;font-weight:700}
#ar-ll .ar-ll-a.low{color:#c2571f}
#ar-ll .ar-ll-p{font-size:18px;font-weight:800;margin-top:6px;color:#1a1a1a}
#ar-ll .ar-ll-c.out .ar-ll-p{color:#888;text-decoration:line-through}
#ar-ll .ar-ll-pill{display:inline-block;margin-top:14px;border:1.5px solid #e8853d;color:#e8853d;border-radius:22px;padding:9px 22px;background:#fff;cursor:pointer;font:600 13px 'Proxima Nova',sans-serif;letter-spacing:.04em}
#ar-ll .ar-ll-pill:hover{background:#e8853d;color:#fff}
#ar-ll .ar-ll-hide{display:none}
#ar-ll .ar-ll-book{display:block;margin-top:16px;font-size:13.5px}
#ar-ll .ar-ll-book a{color:#1d6fb8;text-decoration:none;font-weight:700}
#ar-ll .ar-ll-book a:hover{text-decoration:underline}
#ar-ll .ar-ll-fallback{display:inline-block;background:#E57200;color:#fff;text-decoration:none;font-weight:700;padding:13px 22px;border-radius:9px}
/* selected-confirm toast */
#ar-ll-toast{position:fixed;left:50%;bottom:26px;transform:translate(-50%,16px);opacity:0;background:#2e7d32;color:#fff;padding:13px 20px;border-radius:12px;z-index:999998;font:600 14px 'Proxima Nova',sans-serif;box-shadow:0 6px 24px rgba(0,0,0,.28);max-width:92vw;text-align:center;transition:opacity .3s ease,transform .3s ease;pointer-events:none}
#ar-ll-toast.ar-show{opacity:1;transform:translate(-50%,0)}
#ar-ll-toast b{font-weight:800;letter-spacing:.03em}
.ar-ll-pulse{animation:arLLpulse 1.3s ease-out 2}
@keyframes arLLpulse{0%{box-shadow:0 0 0 0 rgba(201,106,30,.55)}70%{box-shadow:0 0 0 14px rgba(201,106,30,0)}100%{box-shadow:0 0 0 0 rgba(201,106,30,0)}}
/* sticky bottom CTA bar (landing-page equivalent of the loader's #ar-sticky) */
#ar-ll-sticky{position:fixed;left:0;right:0;bottom:0;z-index:999990;background:#1a1a1a;color:#fff;box-shadow:0 -4px 20px rgba(0,0,0,.22);transform:translateY(110%);transition:transform .32s cubic-bezier(.4,0,.2,1);font-family:'Proxima Nova','Helvetica Neue',Arial,sans-serif}
#ar-ll-sticky.ar-show{transform:translateY(0)}
#ar-ll-sticky .ar-sk-in{max-width:1180px;margin:0 auto;display:flex;align-items:center;justify-content:space-between;gap:18px;padding:12px 20px}
#ar-ll-sticky .ar-sk-txt{min-width:0;display:flex;flex-direction:column;line-height:1.3}
#ar-ll-sticky .ar-sk-title{font-size:14px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:62vw}
#ar-ll-sticky .ar-sk-price{font-size:13px;color:#f0c89a;font-weight:600;margin-top:1px}
#ar-ll-sticky.ar-cartmode .ar-sk-price{color:#9fe1cb}
#ar-ll-sticky .ar-sk-btn{flex:none;background:#E57200;color:#fff;border:none;border-radius:24px;padding:11px 26px;font:700 14px 'Proxima Nova','Helvetica Neue',Arial,sans-serif;letter-spacing:.03em;cursor:pointer;white-space:nowrap;transition:background .15s ease,transform .15s ease}
#ar-ll-sticky .ar-sk-btn:hover{background:#c96a1e;transform:translateY(-1px)}
#ar-ll-sticky .ar-sk-btn:active{transform:translateY(0)}
@media (max-width:600px){
  #ar-ll-sticky .ar-sk-in{padding:9px 14px;gap:12px}
  #ar-ll-sticky .ar-sk-title{font-size:13px;max-width:52vw}
  #ar-ll-sticky .ar-sk-price{font-size:12px}
  #ar-ll-sticky .ar-sk-btn{padding:10px 18px;font-size:13px}
}
@media (max-width:600px){
  #ar-ll .ar-ll-g{grid-template-columns:1fr 1fr}
  #ar-ll .ar-ll-sum{grid-template-columns:1fr;column-gap:0}
  #ar-ll .ar-ll-lab{padding:10px 0 2px;border-top:1px solid #efe2cd}
  #ar-ll .ar-ll-val{padding:0 0 8px;border-top:none}
  #ar-ll .ar-ll-strip .c{min-width:calc(50% - 8px)}
}

