.ar-ll-pulse{animation:arLLpulse 1.3s ease-out 2}
@keyframes arLLpulse{0%{box-shadow:0 0 0 0 rgba(201,106,30,.55)}70%{box-shadow:0 0 0 14px rgba(201,106,30,0)}100%{box-shadow:0 0 0 0 rgba(201,106,30,0)}}
/* sticky bottom CTA bar (landing-page equivalent of the loader's #ar-sticky) */
#ar-ll-sticky{position:fixed;left:0;right:0;bottom:0;z-index:999990;background:#1a1a1a;color:#fff;box-shadow:0 -4px 20px rgba(0,0,0,.22);transform:translateY(110%);transition:transform .32s cubic-bezier(.4,0,.2,1);font-family:'Proxima Nova','Helvetica Neue',Arial,sans-serif}
