.ar-hero-wrap{
  --o:#f15a22;--o-dark:#d3420d;--o-darker:#8c2c0a;--o-100:#fbcdb9;--o-50:#fdebe2;
  --cream:#fef7ed;--green:#15803d;--green-dark:#166534;--green-50:#ecfdf5;--navy:#0f172a;
  --body:#1e293b;--muted:#475569;--border:#e2e8f0;--border-strong:#cbd5e1;--slate-50:#f8fafc;
  max-width:1140px;margin:0 auto;padding:1.25rem;
  font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--body);
}
.ar-hero{
  background:linear-gradient(135deg,var(--cream) 0%,var(--o-100) 100%);
  border:1px solid var(--o-100);border-radius:18px;
  padding:2.25rem;box-shadow:0 8px 28px rgba(241,90,34,.10);
}
.ar-hero-top{
  display:grid;grid-template-columns:1.05fr 1fr;gap:2rem;align-items:center;
  margin-bottom:1.75rem;
}
.ar-hero-dash{
  background:var(--navy);border:1px solid var(--border-strong);
  border-radius:14px;overflow:hidden;box-shadow:0 6px 20px rgba(15,23,42,.18);
  transition:transform .2s ease,box-shadow .2s ease;
}
.ar-hero-dash:hover{transform:translateY(-3px);box-shadow:0 12px 30px rgba(15,23,42,.28);}
.ar-hero-dash-top{background:#000;text-align:center;padding:.55rem;}
.ar-hero-dash-badge{
  color:#f5a623;font-size:.72rem;font-weight:800;letter-spacing:.15em;
  border:1px solid #f5a623;border-radius:999px;padding:.2rem .9rem;
}
.ar-hero-dash-body{padding:1.25rem;color:var(--border-strong);}
.ar-hero-dash-head{display:flex;align-items:center;gap:.4rem;margin:0 0 .2rem;}
.ar-hero-dash-head h3{margin:0;font-size:1rem;font-weight:700;color:#fff;}
.ar-hero-dash-body .ar-hero-dash-sub{margin:0 0 1rem;font-size:.72rem;color:#64748b;line-height:1.35;}
.ar-hero-rail{display:flex;justify-content:space-between;margin-bottom:1rem;}
.ar-hero-rail-item{text-align:center;flex:1;}
.ar-hero-rail-dot{width:28px;height:28px;border-radius:50%;background:#334155;margin:0 auto .35rem;transition:transform .15s ease;}
.ar-hero-rail-item:hover .ar-hero-rail-dot{transform:scale(1.18);}
.ar-hero-rail-dot--on{background:var(--green-dark);}
.ar-hero-rail-dot--now{background:var(--o);box-shadow:0 0 0 3px rgba(241,90,34,.25);}
.ar-hero-rail-item span{font-size:.64rem;color:#cbd5e1;}
.ar-hero-tiles{display:grid;grid-template-columns:1fr 1fr;gap:.5rem;}
.ar-hero-tile{background:var(--green-dark);border-radius:7px;padding:.6rem .65rem;transition:transform .15s ease;}
.ar-hero-tile:hover{transform:translateY(-2px);}
.ar-hero-tile--goal{background:#7c4a06;border:1px solid #f5a623;}
.ar-hero-tile p{margin:0;font-size:.72rem;font-weight:700;color:#fff;}
.ar-hero-tile span{display:block;margin-top:.2rem;font-size:.64rem;color:#bbf7d0;line-height:1.35;}
.ar-hero-tile--goal p{color:#fbbf24;}
.ar-hero-tile--goal span{color:#fde68a;}
.ar-hero-dash-cap{text-align:center;font-size:.82rem;color:var(--o-darker);margin:.75rem 0 0;font-weight:600;line-height:1.4;}
.ar-hero-tag{
  display:inline-block;background:var(--o-100);color:var(--o-darker);
  font-size:.74rem;font-weight:800;letter-spacing:.05em;text-transform:uppercase;
  padding:.4rem .85rem;border-radius:999px;border:1px solid var(--o);margin-bottom:1rem;
}
.ar-hero h2{font-size:2.5rem;line-height:1.1;margin:0 0 .7rem;color:var(--o-darker);font-weight:800;}
.ar-hero-lead{font-size:1.08rem;line-height:1.55;color:var(--body);margin:0 0 1.1rem;font-weight:500;}
.ar-hero-lead strong{color:var(--navy);font-weight:700;}
.ar-hero-price{
  display:flex;flex-wrap:wrap;gap:1rem;align-items:baseline;
  padding:.85rem 1rem;background:#fff;border:1px solid var(--o-100);
  border-radius:10px;font-size:.9rem;color:var(--muted);
  transition:box-shadow .2s ease;
}
.ar-hero-price:hover{box-shadow:0 4px 14px rgba(241,90,34,.12);}
.ar-hero-price strong{font-size:1.2rem;color:var(--navy);font-weight:800;}
.ar-hero-price .ar-hero-price-div{color:var(--o-100);}

/* ---- shared hover-tip (info affordance) ---- */
.ar-tip{position:relative;display:inline-flex;align-items:center;justify-content:center;
  width:16px;height:16px;border-radius:50%;border:1.5px solid currentColor;
  font-size:.64rem;font-weight:800;line-height:1;cursor:help;opacity:.7;flex:0 0 auto;}
.ar-tip:hover{opacity:1;}
.ar-tip::after{
  content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;
  transform:translateX(-50%) translateY(4px);width:200px;
  background:var(--navy);color:#fff;font-size:.72rem;font-weight:500;line-height:1.4;
  letter-spacing:0;text-transform:none;padding:.6rem .7rem;border-radius:8px;
  opacity:0;pointer-events:none;transition:opacity .15s ease,transform .15s ease;
  z-index:20;box-shadow:0 6px 20px rgba(15,23,42,.35);text-align:left;}
.ar-tip::before{
  content:"";position:absolute;bottom:calc(100% + 2px);left:50%;
  transform:translateX(-50%);border:6px solid transparent;border-top-color:var(--navy);
  opacity:0;transition:opacity .15s ease;z-index:20;}
.ar-tip:hover::after{opacity:1;transform:translateX(-50%) translateY(0);}
.ar-tip:hover::before{opacity:1;}
.ar-hero-dash-head .ar-tip{color:#f5a623;}
.ar-hero-price .ar-tip{color:var(--o-darker);}

/* ---- ENTRANCE PATHS ---- */
.ar-hero-paths{display:grid;grid-template-columns:1fr 1fr 1fr;gap:1rem;}
.ar-hero-path{
  border-radius:14px;padding:1.35rem 1.3rem;display:flex;flex-direction:column;
  position:relative;transition:transform .18s ease,box-shadow .18s ease;
}
.ar-hero-path--new{background:var(--green-50);border:2px solid var(--green);}
.ar-hero-path--member{background:var(--o-50);border:2px solid var(--o);}
.ar-hero-path--browse{background:var(--slate-50);border:2px solid var(--border-strong);}
.ar-hero-path-tagrow{display:flex;align-items:center;gap:.4rem;margin-bottom:.8rem;}
.ar-hero-path-tag{
  font-size:.7rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase;
  padding:.35rem .8rem;border-radius:999px;color:#fff;
}
.ar-hero-path--new .ar-hero-path-tag{background:var(--green);}
.ar-hero-path--member .ar-hero-path-tag{background:var(--o);}
.ar-hero-path--browse .ar-hero-path-tag{background:#64748b;}
.ar-hero-path--new .ar-tip{color:var(--green-dark);}
.ar-hero-path--member .ar-tip{color:var(--o-darker);}
.ar-hero-path--browse .ar-tip{color:var(--muted);}
.ar-hero-path h3{margin:0 0 .5rem;font-size:1.15rem;font-weight:800;color:var(--navy);line-height:1.25;}
.ar-hero-path p{margin:0 0 1.1rem;font-size:.92rem;color:var(--body);line-height:1.5;}
.ar-hero-path-btn{
  margin-top:auto;width:100%;box-sizing:border-box;text-align:center;
  font-family:inherit;cursor:pointer;line-height:1.2;border-radius:10px;
  font-weight:800;font-size:1rem;padding:.9rem 1rem;display:block;text-decoration:none;
  transition:transform .1s ease,box-shadow .1s ease,background .1s ease;
}
.ar-hero-path--new .ar-hero-path-btn{background:var(--green);color:#fff!important;border:none;box-shadow:0 4px 10px rgba(21,128,61,.3);}
.ar-hero-path--member .ar-hero-path-btn{background:var(--o);color:#fff!important;border:none;box-shadow:0 4px 10px rgba(241,90,34,.35);}
.ar-hero-path--member .ar-hero-path-btn:hover{background:var(--o-dark);}
.ar-hero-path--browse .ar-hero-path-btn{background:#fff;color:var(--navy)!important;border:2px solid var(--border-strong);font-weight:700;}
.ar-hero-path--browse .ar-hero-path-btn:hover{background:#f1f5f9;border-color:var(--muted);}

/* ---- hover lift + subtle wobble (reduced-motion safe) ---- */
@media (prefers-reduced-motion: no-preference){
  @keyframes ar-wobble{
    0%{transform:translateY(-4px) rotate(0deg);}
    25%{transform:translateY(-4px) rotate(-1.4deg);}
    75%{transform:translateY(-4px) rotate(1.4deg);}
    100%{transform:translateY(-4px) rotate(0deg);}
  }
  .ar-hero-path--new:hover{animation:ar-wobble .5s ease;box-shadow:0 12px 26px rgba(21,128,61,.22);}
  .ar-hero-path--member:hover{animation:ar-wobble .5s ease;box-shadow:0 12px 26px rgba(241,90,34,.22);}
  .ar-hero-path--browse:hover{animation:ar-wobble .5s ease;box-shadow:0 12px 26px rgba(15,23,42,.14);}
  .ar-hero-path-btn:hover{transform:translateY(-1px);}
  .ar-hero-path--new .ar-hero-path-btn:hover{box-shadow:0 6px 14px rgba(21,128,61,.42);}
  .ar-hero-path--member .ar-hero-path-btn:hover{box-shadow:0 6px 14px rgba(241,90,34,.5);}
}
@media (prefers-reduced-motion: reduce){
  .ar-hero-path--new:hover{box-shadow:0 12px 26px rgba(21,128,61,.22);}
  .ar-hero-path--member:hover{box-shadow:0 12px 26px rgba(241,90,34,.22);}
  .ar-hero-path--browse:hover{box-shadow:0 12px 26px rgba(15,23,42,.14);}
}

@media (max-width:900px){
  .ar-hero-top{grid-template-columns:1fr;gap:1.5rem;}
