  width:16px;height:16px;border-radius:50%;border:1.5px solid currentColor;color:var(--green-dark);
  font-size:.64rem;font-weight:800;line-height:1;cursor:help;opacity:.7;flex:0 0 auto;}
.ar-tip:hover{opacity:1;}
.ar-tip::after{
  content:attr(data-tip);position:absolute;bottom:calc(100% + 8px);left:50%;
  transform:translateX(-50%) translateY(4px);width:210px;
  background:var(--navy);color:#fff;font-size:.72rem;font-weight:500;line-height:1.4;
  letter-spacing:0;text-transform:none;padding:.6rem .7rem;border-radius:8px;
