  z-index:20;box-shadow:0 6px 20px rgba(15,23,42,.35);text-align:left;}
.ar-tip::before{
  content:"";position:absolute;bottom:calc(100% + 2px);left:50%;
  transform:translateX(-50%);border:6px solid transparent;border-top-color:var(--navy);
  opacity:0;transition:opacity .15s ease;z-index:20;}
.ar-tip:hover::after{opacity:1;transform:translateX(-50%) translateY(0);}
.ar-tip:hover::before{opacity:1;}

/* hover lift + subtle wobble (reduced-motion safe) */
@media (prefers-reduced-motion: no-preference){
  @keyframes ar-wobble{
