/* shared hover-tip (opens DOWNWARD into the card body so it isn't clipped).
   White outline for the orange header; orange outline for inline body tips. */
.ar-get-tip{position:relative;display:inline-flex;align-items:center;justify-content:center;
  width:16px;height:16px;border-radius:50%;border:1.5px solid rgba(255,255,255,.85);color:#fff;
  font-size:.64rem;font-weight:800;line-height:1;cursor:help;opacity:.9;flex:0 0 auto;}
.ar-get-tip--inline{border-color:var(--o);color:var(--o-darker);vertical-align:middle;}
.ar-get-tip:hover{opacity:1;}
.ar-get-tip::after{
  content:attr(data-tip);position:absolute;top:calc(100% + 8px);left:50%;
  transform:translateX(-50%) translateY(-4px);width:220px;
  background:#000;color:#fff;font-size:.72rem;font-weight:500;line-height:1.4;
  letter-spacing:0;text-transform:none;padding:.6rem .7rem;border-radius:8px;
  opacity:0;pointer-events:none;transition:opacity .15s ease,transform .15s ease;
  z-index:30;box-shadow:0 6px 20px rgba(0,0,0,.5);text-align:left;}
.ar-get-tip::before{
  content:"";position:absolute;top:calc(100% + 2px);left:50%;
  transform:translateX(-50%);border:6px solid transparent;border-bottom-color:#000;
  opacity:0;transition:opacity .15s ease;z-index:30;}
.ar-get-tip:hover::after{opacity:1;transform:translateX(-50%) translateY(0);}
.ar-get-tip:hover::before{opacity:1;}
/* header tips (right-aligned in the strip) open down-left so they stay on-card */
.ar-get-card-head .ar-get-tip::after{left:auto;right:0;transform:translateX(0) translateY(-4px);}
.ar-get-card-head .ar-get-tip:hover::after{transform:translateX(0) translateY(0);}
.ar-get-card-head .ar-get-tip::before{left:auto;right:5px;transform:none;}

/* hover lift + subtle wobble (reduced-motion safe) */
@media (prefers-reduced-motion: no-preference){
  @keyframes ar-wobble{
    0%{transform:translateY(-4px) rotate(0deg);}
    25%{transform:translateY(-4px) rotate(-1deg);}
    75%{transform:translateY(-4px) rotate(1deg);}
    100%{transform:translateY(-4px) rotate(0deg);}
  }
  .ar-get-card:hover{animation:ar-wobble .5s ease;box-shadow:0 16px 34px rgba(0,0,0,.38);}
}
@media (prefers-reduced-motion: reduce){
  .ar-get-card:hover{transform:translateY(-4px);box-shadow:0 16px 34px rgba(0,0,0,.38);}
}

@media (max-width:900px){
  .ar-get-shell{padding:1.25rem;}
  .ar-get-grid{grid-template-columns:1fr;}
  .ar-get-banner h2{font-size:1.35rem;}
  .ar-get-banner-cta{width:100%;}
  .ar-get-cta-btn{width:100%;box-sizing:border-box;}
  .ar-get-tip::after{width:180px;}
}

