.ar-prop .ar-concl h2{font-size:24px;font-weight:800;color:#fff;margin:0 0 10px}
.ar-prop .ar-concl p{font-size:15px;font-weight:600;color:#d9d2c9;margin:0 0 18px}
.ar-prop .ar-concl-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:0 0 20px;text-align:left}
.ar-prop .ar-cc{display:block;text-decoration:none;background:var(--orange);border:1px solid var(--orange-d);border-radius:12px;padding:16px;box-shadow:0 6px 16px rgba(229,114,0,.28);transition:transform .15s ease,box-shadow .15s ease;cursor:pointer}
.ar-prop .ar-cc:hover{box-shadow:0 10px 24px rgba(229,114,0,.45);animation:ar-wobble .5s ease-in-out infinite}
.ar-prop .ar-cc h3{font-size:14.5px;font-weight:800;color:#fff;margin:0 0 6px}
.ar-prop .ar-cc p{font-size:12.5px;color:#ffe9d2;margin:0 0 10px}
.ar-prop .ar-cc span{color:#fff;font-weight:800;text-decoration:underline;font-size:13px}
.ar-prop .ar-concl .ar-btn{max-width:340px;margin:0 auto 9px}
@keyframes ar-wobble{
  0%{transform:translateY(-3px) rotate(0deg)}
  25%{transform:translateY(-3px) rotate(-2.5deg)}
  50%{transform:translateY(-3px) rotate(0deg)}
  75%{transform:translateY(-3px) rotate(2.5deg)}
  100%{transform:translateY(-3px) rotate(0deg)}
}
@media(prefers-reduced-motion:reduce){.ar-cc:hover{animation:none;transform:translateY(-3px)}}

@media(max-width:760px){
  .ar-prop .ar-hero{grid-template-columns:1fr}
  .ar-prop .ar-grid2, .ar-prop .ar-steps, .ar-prop .ar-concl-grid, .ar-prop .ar-curgrid{grid-template-columns:1fr}
  .ar-prop .ar-curgrid{grid-template-columns:1fr 1fr}
  .ar-prop .ar-h2{font-size:20px}
}

