#ar-pnm-acc .ar-item::before{content:'\2713';position:absolute;left:0;color:#1e8e3e;font-weight:800}
#ar-pnm-acc strong{color:#111827;font-weight:800}
#ar-pnm-acc a{color:#c45f00 !important;font-weight:800;text-decoration:none}
#ar-pnm-acc a:hover{text-decoration:underline}
#ar-pnm-acc .ar-bank{display:inline-block;background:#fff;border:1px solid #efe3d4;border-radius:8px;padding:8px 12px;margin:2px 0 8px;font-weight:700}

