.ar-gv-cann-box{
  border:1px solid #e6e6e6;
  border-radius:12px;
  padding:20px 22px;
  margin:16px 0;
  background:linear-gradient(180deg,#fffaf4 0%,#fff 55%);
  box-shadow:0 6px 18px rgba(0,0,0,.05);
  color:#1f242a;
  line-height:1.5;
  font-size:16px;
}
.ar-gv-cann-title{
  margin:0 0 10px;
  font-size:clamp(18px,2.2vw,22px);
  font-weight:800;
  color:#1f1205;
  letter-spacing:-.01em;
}
.ar-gv-cann-lead{margin:0 0 12px;font-weight:600;color:#2a3036}
.ar-gv-cann-points{margin:0 0 14px;padding-left:1.2em;font-weight:600;color:#3a4148}
.ar-gv-cann-points li{margin:0.35em 0}
.ar-gv-cann-cta{margin:0 0 10px;font-weight:600}
.ar-gv-cann-box a{color:#c45f00 !important;font-weight:800;text-decoration:none}
.ar-gv-cann-box a:hover{text-decoration:underline}
/* Squarespace button override — force white text on orange */
.ar-gv-cann-box a.ar-gv-cann-btn,
.ar-gv-cann-box a.ar-gv-cann-btn:link,
.ar-gv-cann-box a.ar-gv-cann-btn:visited,
.ar-gv-cann-box a.ar-gv-cann-btn:hover,
.ar-gv-cann-box a.ar-gv-cann-btn:active,
.ar-gv-cann-box a.ar-gv-cann-btn:focus,
.ar-gv-cann-box a.ar-gv-cann-btn span{
  display:inline-block !important;
  margin-left:6px;
  padding:10px 16px !important;
  border-radius:8px !important;
  background:#E57200 !important;
  background-color:#E57200 !important;
  color:#ffffff !important;
  font-weight:800 !important;
  text-decoration:none !important;
  border:none !important;
  box-shadow:none !important;
  -webkit-text-fill-color:#ffffff !important;
}
.ar-gv-cann-box a.ar-gv-cann-btn:hover,
.ar-gv-cann-box a.ar-gv-cann-btn:hover span{
  background:#c45f00 !important;
  background-color:#c45f00 !important;
  color:#ffffff !important;
  text-decoration:none !important;
  -webkit-text-fill-color:#ffffff !important;
}
.ar-gv-cann-note{margin:0;font-size:13px;font-weight:600;color:#6b7280}
@media(max-width:520px){
  .ar-gv-cann-box a.ar-gv-cann-btn{
    display:block !important;
    margin:10px 0 0 !important;
    text-align:center;
    color:#ffffff !important;
    -webkit-text-fill-color:#ffffff !important;
  }
}

